.wsmamabelt__sred{display:grid;grid-template-columns:1fr minmax(240px,340px) 1fr;gap:36px;align-items:center;margin-top:18px}.wsmamabelt__sc{display:flex;flex-direction:column;gap:28px}.wsmamabelt__sf strong{display:block;font-size:19px;font-weight:800;margin:0 0 6px}.wsmamabelt__sf strong::after{content:'';display:inline-block;width:9px;height:9px;border-radius:50%;background:#d58a28;margin-left:8px;vertical-align:middle}.wsmamabelt__sf p{margin:0;font-size:15px;line-height:1.6;color:#333}.wsmamabelt__sm img,.wsmamabelt__sm video{width:100%;height:auto;display:block}
.wsmamabelt__karw{position:relative}.wsmamabelt__kar{grid-auto-flow:column;grid-auto-columns:calc((100% - 44px)/3);grid-template-columns:none!important;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none}.wsmamabelt__kar::-webkit-scrollbar{display:none}.wsmamabelt__kar>*{scroll-snap-align:start}
.wsmamabelt__pus{position:absolute;top:50%;transform:translateY(-50%);width:42px;height:42px;border-radius:50%;border:0;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.18);font-size:22px;line-height:42px;cursor:pointer;z-index:2;color:#1d2b4f;padding:0}.wsmamabelt__pus--l{left:-14px}.wsmamabelt__pus--d{right:-14px}
@media (max-width:860px){.wsmamabelt__kar{grid-auto-columns:82%}.wsmamabelt__pus--l{left:4px}.wsmamabelt__pus--d{right:4px}}
@media (max-width:860px){.wsmamabelt__s{padding:38px 0}.wsmamabelt__dva{grid-template-columns:1fr;gap:22px}.wsmamabelt__dva--rev>div:first-child{order:0}
.wsmamabelt__sred{grid-template-columns:1fr;gap:22px}.wsmamabelt__sm{max-width:300px;margin:0 auto;order:-1}.wsmamabelt__g3,.wsmamabelt__g4,.wsmamabelt__g5{grid-template-columns:1fr 1fr}.wsmamabelt__red4{grid-template-columns:1fr 1fr}.wsmamabelt__plavo{margin-top:-38px}}
@media (max-width:560px){.wsmamabelt__g2,.wsmamabelt__g3,.wsmamabelt__g4{grid-template-columns:1fr}}
.wsmamabelt__polna--ar img,.wsmamabelt__polna--ar video{aspect-ratio:var(--ar);object-fit:cover;height:auto}
@media (max-width:560px){.wsmamabelt__polna--ar img,.wsmamabelt__polna--ar video{aspect-ratio:4/3}}
@media (max-width:560px){.wsmamabelt__tab{font-size:13px}.wsmamabelt__tab th,.wsmamabelt__tab td{padding:10px 6px}.wsmamabelt__tab th:first-child,.wsmamabelt__tab td:first-child{padding-left:10px}}
