.wsmamabelt__s{padding:72px 0}.wsmamabelt__s.wsmamabelt__s--bg{background:#fdefee}.wsmamabelt__s.wsmamabelt__traka{padding:40px 0}.wsmamabelt__s.wsmamabelt__traka:not(.wsmamabelt__s--bg){background:#fff}
.wsmamabelt__kicker{color:#9c6462;letter-spacing:1.8px;font-size:12.5px}.wsmamabelt__kicker::before{content:"";display:inline-block;width:22px;height:2px;background:#f19a96;vertical-align:middle;margin:-2px 10px 0 0;border-radius:2px}
.wsmamabelt__h2 em{color:#9c6462}.wsmamabelt__dva .wsmamabelt__zak{border-left:3px solid #f19a96;padding-left:14px}
.wsmamabelt__media,.wsmamabelt__polna{box-shadow:0 14px 34px rgba(241,154,150,.22);border:1px solid rgba(241,154,150,.25)}
.wsmamabelt__k{border:1px solid rgba(241,154,150,.35);border-radius:16px;box-shadow:0 6px 18px rgba(0,0,0,.05);transition:transform .2s,box-shadow .2s}.wsmamabelt__k:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(241,154,150,.22)}
