span.wsmamabelt__pi{opacity:1;width:58px;height:58px;border-radius:50%;background:#fbe1e0;border:1px solid #f19a96;color:#9c6462;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.wsmamabelt__pi svg{width:28px;height:28px}
.wsmamabelt__red4:not(.wsmamabelt__pog)>div{background:#fff;border:1px solid rgba(241,154,150,.35);border-radius:16px;padding:24px 16px;box-shadow:0 6px 18px rgba(0,0,0,.05)}.wsmamabelt__red3 span.wsmamabelt__pi{width:44px;height:44px;margin-bottom:8px}.wsmamabelt__red3 .wsmamabelt__pi svg{width:22px;height:22px}.wsmamabelt__red3>div{border-color:rgba(241,154,150,.35)}
.wsmamabelt__pog strong{color:#1c1c1c}.wsmamabelt__st,.wsmamabelt__kv li::before{background:#9c6462}.wsmamabelt__tab th{background:#9c6462!important}
.wsmamabelt__ti{background:linear-gradient(135deg,#9c6462,#b28685);box-shadow:0 6px 14px rgba(156,100,98,.30)}.wsmamabelt__tk{border-color:rgba(241,154,150,.30)}
.wsmamabelt__ime{display:flex;align-items:center;gap:10px}.wsmamabelt__av{flex:0 0 34px;width:34px;height:34px;border-radius:50%;background:#fbe1e0;border:1px solid #f19a96;color:#9c6462;font-style:normal;font-weight:800;font-size:14px;display:inline-flex;align-items:center;justify-content:center}
div.wsmamabelt__pog{text-align:center;border:1px solid rgba(241,154,150,.35);border-radius:16px;transition:transform .2s,box-shadow .2s}div.wsmamabelt__pog:hover{transform:translateY(-3px);box-shadow:0 14px 30px rgba(241,154,150,.22)}div.wsmamabelt__pog>strong,div.wsmamabelt__pog>span:not(.wsmamabelt__pi){display:block}
.wsmamabelt__k--ik .wsmamabelt__kt{text-align:center;padding:28px 20px}
.wsmamabelt__pus{color:#9c6462}.wsmamabelt__plavo{background:#9c6462;margin-top:-72px}.wsmamabelt__k--temna{background:#9c6462}
@media (max-width:860px){.wsmamabelt__s{padding:46px 0}.wsmamabelt__s.wsmamabelt__traka{padding:30px 0}.wsmamabelt__plavo{margin-top:-46px}.wsmamabelt__pog>div{padding:22px 12px}}
@media (max-width:767px){.wsmamabelt__v{padding:0 16px}}
/* /dizajn.py */
.wsmamabelt__v>.wsmamabelt__zak{text-align:center}
</style>
<script>
(function(){document.querySelectorAll('.wsmamabelt__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wsmamabelt__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wsmamabelt__pus wsmamabelt__pus--'+s;b.setAttribute('aria-label',s==='l'?'Prethodno':'Sljedeće');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
